def get_song_feature_vector(song: dict) -> "np.ndarray":
    """Returns a normalized 21-dim feature vector for a song.

    Dimensions:
      0  - tempo (normalized 0-1)
      1  - energy
      2  - valence
      3  - danceability
      4  - acousticness
      5  - instrumentalness
      6  - loudness
      7  - log-normalized play_count
      8  - release_year (normalized)
      9-20 - genre one-hot (12 genres)
    """
    genre_idx = GENRES.index(song["genre"])
    genre_onehot = np.zeros(len(GENRES))
    genre_onehot[genre_idx] = 1.0

    features = np.array([
        song["tempo"] / 180.0,
        song["energy"],
        song["valence"],
        song["danceability"],
        song["acousticness"],
        song["instrumentalness"],
        song["loudness"],
        np.log1p(song["play_count"]) / np.log1p(50_000_000),
        (song["release_year"] - 1980) / 44.0,
    ])
    return np.concatenate([features, genre_onehot])


SONGS_DB = {song["id"]: song for song in SONGS_LIST}
